param(
    [Parameter(Mandatory=$true)][string]$CompiledClasses,
    [Parameter(Mandatory=$true)][string]$AndroidJar,
    [Parameter(Mandatory=$true)][string]$XposedApiJar,
    [string]$JdkBin='',
    [string]$CheckOutput=''
)
$ErrorActionPreference='Stop'
$c17ValidationRoot=$PSScriptRoot
$c17CheckOutput=if($CheckOutput){[System.IO.Path]::GetFullPath($CheckOutput)}else{Join-Path $c17ValidationRoot 'build-checks'}
$c17Json=Join-Path $c17ValidationRoot 'test-libs\json-20240303.jar'
if(-not(Test-Path -LiteralPath $c17Json)){throw 'Missing desktop JSON test runtime'}
New-Item -ItemType Directory -Force -Path $c17CheckOutput | Out-Null
. (Join-Path $c17ValidationRoot 'check-runtime-dependencies.ps1')
$taskCoreJar=Get-C17CheckCoreJar $c17CheckOutput
$c17Java=if($JdkBin){Join-Path $JdkBin 'java.exe'}else{'java'}
$c17Javac=if($JdkBin){Join-Path $JdkBin 'javac.exe'}else{'javac'}
$c17Sources=Get-ChildItem -LiteralPath (Join-Path $c17ValidationRoot 'checks-src') -Filter '*.java' -Recurse | ForEach-Object {$_.FullName}
# Keep Windows' process-command length independent of the fixture count. javac
# reads UTF-8 paths from its own argument file; no shell expansion is involved.
$c17SourceArgs=Join-Path $c17CheckOutput 'check-sources.args'
$c17QuotedSources=@($c17Sources)+(Join-Path $c17ValidationRoot 'SettingsCheck.java') | ForEach-Object {'"'+$_.Replace('\','/')+'"'}
[System.IO.File]::WriteAllLines($c17SourceArgs,[string[]]$c17QuotedSources,[System.Text.UTF8Encoding]::new($false))
& $c17Javac '-J-Dfile.encoding=UTF-8' -J-Xms16m -J-Xmx256m -J-XX:+UseSerialGC -encoding UTF-8 -classpath "$CompiledClasses;$XposedApiJar;$c17Json;$taskCoreJar;$AndroidJar" -d $c17CheckOutput ("@"+$c17SourceArgs)
if($LASTEXITCODE-ne 0){throw 'Check compilation failed'}
